class Rational {
    int numer;
    int denom;
    Rational(int numer, int denom) {
        this.numer = numer;
        this.denom = denom;
    }
    Rational add(Rational r) {
        int x = numer * r.denom + r.numer * denom;
        int y = denom * r.denom;
        return new Rational(x, y);
    }
    void inc(int k) {
        numer = numer + k * denom;
    }
    public String toString() {
        return numer + "/" + denom;
    }
}
