class Node {
    int info;
    Node next;
    Node(int info, Node next) {
        this.info = info;
        this.next = next;
    }
    static Node merge(Node a, Node b) {
        if (a == null) {
            return b;
        }
        if (b == null) {
            return a;
        }
        if (a.info <= b.info) {
            a.next = merge(a.next, b);
            return a;
        } else {
            b.next = merge(a, b.next);
            return b;
        }
    }
}

