class List {
    int info;
    List next;
    List(int info, List next) {
        this.info = info;
        this.next = next;
    }
    static List arrayToList(int[] a) {
        List result = null;
        for (int i = a.length - 1; i >= 0; --i) {
            result = new List(a[i], result);
        }
        return result;
    }
}
